cd /home/ubuntu/.agent-ml-research-idea_gen_0509_3/projects/solver-trace-ablation/paper && python3 -c "
import subprocess
# Get page-by-page text to find which pages Table 8 and Figure 5 land on
for page in range(14, 24):
    result = subprocess.run(['pdftotext', '-f', str(page), '-l', str(page), 'main.pdf', '-'], capture_output=True, text=True)
    text = result.stdout
    markers = []
    if 'Table 8' in text: markers.append('Table 8')
    if 'Figure 5' in text: markers.append('Figure 5')
    if 'Table 9' in text: markers.append('Table 9')
    if 'Figure 4' in text: markers.append('Figure 4')
    if 'Table 10' in text: markers.append('Table 10')
    if markers:
        print(f'Page {page}: {markers}')
" 2>&1

